input.old_string:
&__title {
  @include typography('md', 'medium');
  color: color('text');
  white-space: nowrap;

  &--done {
    text-decoration: line-through;
    color: color('text-secondary');
  }
}

input.new_string:
&__title {
  @include typography('md', 'medium');
  @include truncate;
  color: color('text');
  flex: 1;
  min-width: 0;

  &--done {
    text-decoration: line-through;
    color: color('text-secondary');
  }
}

&__list-name {
  display: inline-flex;
  align-items: center;
  gap: spacing(1);
  flex-shrink: 0;
  @include status-badge(color('border-light'), color('text-secondary'));
}

&__list-icon {
  flex-shrink: 0;
}
